  content: string;
}

export async function exportVaultToEncryptedZip(
  files: ExportFile[],
  pin: string
): Promise<Blob> {
  const zip = new JSZip();

  // Bundle markdown files, sidecars, and configuration
  files.forEach((f) => {
    zip.file(f.name, f.content);
  });

  // Add metadata/plugins config mock file
  zip.file('.anymd/plugins/config.json', JSON.stringify({
    version: '1.0',
    rebranded: true,
    mbbEnabled: true,
  }, null, 2));

  // Generate ZIP as array buffer
  const zipBuffer = await zip.generateAsync({ type: 'arraybuffer' });

  // Setup Encryption
  const salt = window.crypto.getRandomValues(new Uint8Array(16));
  const iv = window.crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveKeyFromPin(pin, salt);

  const encryptedContent = await window.crypto.subtle.encrypt(
    {
      name: 'AES-GCM',
      iv,
    },
    key,
    zipBuffer
  );

  // Combine salt + iv + encrypted content into a final output blob
  const finalBuffer = new Uint8Array(salt.length + iv.length + encryptedContent.byteLength);
  finalBuffer.set(salt, 0);
  finalBuffer.set(iv, salt.length);
  finalBuffer.set(new Uint8Array(encryptedContent), salt.length + iv.length);

  return new Blob([finalBuffer], { type: 'application/zip' });
}
"

"import JSZip from 'jszip';
import { deriveKeyFromPin } from './zipVaultExporter';

interface ImportedFile {
  name: string;
  content: string;
}

export async function importVaultFromEncryptedZip(
  encryptedData: ArrayBuffer,
  pin: string
): Promise<ImportedFile[]> {
  try {
    const dataView = new Uint8Array(encryptedData);

    // Extract salt, iv and cipher text
    const salt = dataView.slice(0, 16);
    const iv = dataView.slice(16, 28);
    const encryptedContent = dataView.slice(28);

    const key = await deriveKeyFromPin(pin, salt);

    const decryptedBuffer = await window.crypto.subtle.decrypt(
      {
        name: 'AES-GCM',
        iv,
      },
      key,
      encryptedContent
    );

    // Load decrypted zip buffer
    const zip = await JSZip.loadAsync(decryptedBuffer);
    const files: ImportedFile[] = [];

    // Unpack hierarchy
    const fileKeys = Object.keys(zip.files);
    for (const key of fileKeys) {
      const zFile = zip.files[key];
      if (!zFile.dir) {
        const text = await zFile.async('text');
        files.push({
          name: zFile.name,
          content: text,
        });
      }
    }

    return files;
  } catch (err) {
    console.error('Decryption/Import failed:', err);
    throw new Error('Invalid PIN or corrupted archive.');
  }
}
"

